import React from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import toast from 'react-hot-toast';

const Navbar = () => {
  const navigate = useNavigate();
  const { user, logout } = useAuth();

  const handleLogout = () => {
    logout();
    toast.success('Logged out successfully');
    navigate('/login');
  };

  return (
    <nav style={{
      background: 'white',
      padding: '12px 30px',
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      borderBottom: '1px solid #e9ecef',
      position: 'sticky',
      top: 0,
      zIndex: 1000,
    }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: '20px', cursor: 'pointer' }} onClick={() => navigate('/')}>
        <h1 style={{ 
          fontSize: '22px', 
          fontWeight: 700,
          color: '#1a1a2e',
        }}>
          ⚡ CodeArena
        </h1>
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: '20px' }}>
        <button onClick={() => navigate('/problems')} style={styles.navLink}>
          📚 Problems
        </button>
        <button onClick={() => navigate('/submissions')} style={styles.navLink}>
          📊 Submissions
        </button>
        {(user?.role === 'admin' || user?.role === 'setter') && (
          <button onClick={() => navigate('/create-problem')} style={styles.navLink}>
            ➕ Create
          </button>
        )}
        <span style={{ color: '#666', fontSize: '14px' }}>|</span>
        <span style={{ fontSize: '14px', color: '#333', fontWeight: 500 }}>
          👤 {user?.username}
        </span>
        <button onClick={handleLogout} style={styles.logoutBtn}>
          Logout
        </button>
      </div>
    </nav>
  );
};

const styles = {
  navLink: {
    background: 'transparent',
    color: '#555',
    border: 'none',
    padding: '8px 12px',
    borderRadius: '6px',
    cursor: 'pointer',
    fontSize: '14px',
    fontWeight: 500,
    transition: 'all 0.3s',
  },
  logoutBtn: {
    padding: '6px 16px',
    background: '#f44336',
    color: 'white',
    border: 'none',
    borderRadius: '6px',
    cursor: 'pointer',
    fontSize: '13px',
    fontWeight: 500,
  },
};

export default Navbar;
